// 1. Comprehensive Curated Schemes Dataset
const schemes = [
  // --- Employment, Education & Research ---
  {
    name: "National Career Service (NCS) Scheme",
    category: "Employment & Research",
    minEducation: "Diploma",
    targetSkills: ["History", "Research", "Teaching", "Communication", "Admin"],
    description: "Provides job matching, career counseling, and fellowship guidance for researchers and graduates."
  },
  {
    name: "Pandit Madan Mohan Malaviya National Mission on Teachers and Teaching",
    category: "Education",
    minEducation: "Degree",
    targetSkills: ["Teaching", "Education", "Communication", "Mentoring", "History"],
    description: "Focuses on capacity building and professional development for educators and teaching assistants."
  },

  // --- Agriculture ---
  {
    name: "Rashtriya Krishi Vikas Yojana (RKVY)",
    category: "Agriculture",
    minEducation: "Any",
    targetSkills: ["Farming", "Agriculture", "Animal care", "Physical labor", "Crop management"],
    description: "Supports farming practices, agri-entrepreneurship, and skill development in the allied agriculture sector."
  },

  // --- Construction & Labour ---
  {
    name: "BOCW (Building and Other Construction Workers) Welfare Scheme",
    category: "Construction & Labour",
    minEducation: "Any",
    targetSkills: ["Physical labor", "Basic tools", "Masonry", "Construction"],
    description: "Provides financial assistance, health coverage, tool kits, and skill upgrades for construction workers."
  },

  // --- Arts & Handicrafts ---
  {
    name: "Ambedkar Hastshilp Vikas Yojana",
    category: "Arts & Handicrafts",
    minEducation: "Any",
    targetSkills: ["Handicrafts", "Weaving", "Arts & Crafts", "Painting", "Art", "Tailoring", "Stitching"],
    description: "Empowers artisans through skill enhancement, design interventions, tool kits, and market linkages."
  },

  // --- Domestic Service & Unorganized Labour ---
  {
    name: "PM Shram Yogi Maandhan (PM-SYM)",
    category: "Domestic Service",
    minEducation: "Any",
    targetSkills: ["Housekeeping", "Cooking", "Food prep", "Driving", "Domestic Service"],
    description: "A voluntary and contributory pension scheme for unorganized workers, including domestic helpers, drivers, and street vendors."
  },

  // --- Small Business / Retail ---
  {
    name: "Pradhan Mantri Mudra Yojana (PMMY)",
    category: "Small Business",
    minEducation: "Any",
    targetSkills: ["Sales", "Retail", "Communication", "Basic math", "Tailoring", "Arts & Crafts"],
    description: "Provides micro-credit and non-collateral loans to non-corporate, non-farm small/micro enterprises to start or expand businesses."
  },

  // --- IT & Computer Science ---
  {
    name: "FutureSkills Prime (MeitY & NASSCOM)",
    category: "IT & CS",
    minEducation: "Diploma",
    targetSkills: ["Basic Computer", "Programming", "IT Support", "Networking basics", "Data Entry", "MS Excel"],
    description: "A digital skilling platform offering certifications in emerging technologies and professional IT skills."
  },

  // --- Engineering Sector ---
  {
    name: "National Apprenticeship Training Scheme (NATS)",
    category: "Engineering & Technical",
    minEducation: "Diploma",
    targetSkills: ["Engineering", "Manufacturing", "Machine operation", "Technical maintenance"],
    description: "A one-year program equipping technically qualified youth with practical knowledge and skills required in their field of work."
  },

  // --- Health Sector ---
  {
    name: "Ayushman Bharat Skill Development Initiative",
    category: "Healthcare",
    minEducation: "10th Pass",
    targetSkills: ["Basic health knowledge", "Caregiving", "First Aid", "Communication"],
    description: "Training programs to create skilled frontline health workers, patient care assistants, and support staff."
  },

  // --- General Skill Development ---
  {
    name: "PMKVY (Pradhan Mantri Kaushal Vikas Yojana)",
    category: "Skill Development",
    minEducation: "Any",
    targetSkills: ["Physical labor", "Basic tools", "Tailoring", "Basic Computer", "Retail", "Food prep"],
    description: "Free industry-relevant skill training and certification across various sectors to enable better livelihoods."
  }
];
// 2. Extract profile data from previous nodes
const profile = $('Profile Agent').first().json.output || $('Profile Agent').first().json;
const userSkills = profile.skills || [];
const userEducation = profile.education_level || "Any";

// 3. Match & Score Schemes
const scoredSchemes = schemes.map(scheme => {
  let score = 0;

  // Check if any user skill matches the target skills of the scheme
  const skillMatch = scheme.targetSkills.some(targetSkill =>
    userSkills.some(userSkill => userSkill.toLowerCase().includes(targetSkill.toLowerCase()))
  );

  if (skillMatch) score += 2;

  // Check education level
  if (scheme.minEducation === "Any" || userEducation.toLowerCase().includes(scheme.minEducation.toLowerCase())) {
    score += 1;
  }

  return {
    ...scheme,
    matchScore: score
  };
});

// 4. Sort and return top 3 schemes
const topSchemes = scoredSchemes
  .sort((a, b) => b.matchScore - a.matchScore)
  .slice(0, 3);

return topSchemes.map(scheme => ({ json: scheme }));

// 1. Comprehensive Curated Courses Dataset
const courses = [
  // --- Education, History & Research ---
  {
    courseName: "History of Indian Science and Technology",
    platform: "NPTEL",
    category: "Education & Research",
    targetSkills: ["History", "Research", "Analytical Thinking"],
    description: "Explores the evolution of science and technology in the Indian subcontinent, ideal for researchers and historians."
  },
  {
    courseName: "Academic Writing and Research",
    platform: "SWAYAM",
    category: "Education & Research",
    targetSkills: ["Research", "Writing", "Teaching", "History"],
    description: "Develops foundational research and academic writing skills for higher education roles."
  },

  // --- Agriculture ---
  {
    courseName: "Organic Farming for Sustainable Agriculture",
    platform: "NPTEL",
    category: "Agriculture",
    targetSkills: ["Farming", "Agriculture", "Crop management"],
    description: "Learn modern organic farming techniques, soil health management, and sustainable practices."
  },

  // --- Construction & Labour ---
  {
    courseName: "Project Planning & Control (Construction)",
    platform: "NPTEL",
    category: "Construction",
    targetSkills: ["Masonry", "Construction", "Physical labor", "Basic tools"],
    description: "Upskill from manual labor/masonry to site supervision and construction project management."
  },

  // --- Arts & Handicrafts ---
  {
    courseName: "Appreciation of Indian Art and Architecture",
    platform: "SWAYAM",
    category: "Arts & Handicrafts",
    targetSkills: ["Art", "Painting", "Handicrafts", "Weaving", "History"],
    description: "Deep dive into traditional Indian art forms, adding historical context and value to handicraft creation."
  },
  {
    courseName: "Textile Design and Development",
    platform: "Skill India / NPTEL",
    category: "Arts & Handicrafts",
    targetSkills: ["Tailoring", "Stitching", "Arts & Crafts", "Weaving"],
    description: "Advanced techniques in textile weaving, natural dyeing, and pattern design."
  },

  // --- Domestic Service & Hospitality ---
  {
    courseName: "Food and Nutrition / Food Safety",
    platform: "SWAYAM",
    category: "Domestic Service",
    targetSkills: ["Cooking", "Housekeeping", "Food prep", "Hospitality"],
    description: "Certification in food safety and professional nutritional cooking to upgrade to professional kitchen roles."
  },

  // --- Small Business / Retail ---
  {
    courseName: "Entrepreneurship and IP Strategy",
    platform: "NPTEL",
    category: "Small Business",
    targetSkills: ["Sales", "Retail", "Communication", "Basic math"],
    description: "Learn how to scale a small business, manage finances, and build a brand."
  },

  // --- IT & Computer Science ---
  {
    courseName: "Programming, Data Structures and Algorithms in Python",
    platform: "NPTEL",
    category: "IT & CS",
    targetSkills: ["Basic Computer", "Programming", "IT Support", "Data Entry"],
    description: "A foundational computer science course to transition from basic IT/Data Entry to software development."
  },

  // --- Engineering Sector ---
  {
    courseName: "Manufacturing Process Technology",
    platform: "NPTEL",
    category: "Engineering",
    targetSkills: ["Engineering", "Manufacturing", "Machine operation", "Basic tools"],
    description: "Covers conventional and advanced manufacturing processes for technical and engineering roles."
  },

  // --- Health Sector ---
  {
    courseName: "Health Research Fundamentals",
    platform: "SWAYAM",
    category: "Healthcare",
    targetSkills: ["Basic health knowledge", "Caregiving", "First Aid", "Research"],
    description: "Basic epidemiology and bio-statistics for healthcare workers looking to move into clinical research or administration."
  }
];

// 2. Extract profile data
// Adjust these node names if yours differ slightly
const profile = $('Profile Agent').first().json.output || $('Profile Agent').first().json;
const userSkills = profile.skills || [];
const interestArea = profile.interest_area || ""; 

// 3. Match & Score Courses (The "Gap" Logic)
const scoredCourses = courses.map(course => {
  let score = 0;

  // Boost score if the course aligns with their stated interest area
  if (interestArea && course.category.toLowerCase().includes(interestArea.toLowerCase())) {
    score += 3; 
  }

  if (interestArea && course.targetSkills.some(skill => skill.toLowerCase().includes(interestArea.toLowerCase()))) {
    score += 2;
  }

  // Check if existing skills overlap with the course's target skills (upskilling path)
  const skillMatch = course.targetSkills.some(targetSkill =>
    userSkills.some(userSkill => userSkill.toLowerCase().includes(targetSkill.toLowerCase()))
  );

  if (skillMatch) score += 1;

  return {
    ...course,
    matchScore: score
  };
});

// 4. Sort and return top 3 recommended courses for the roadmap
const topCourses = scoredCourses
  .sort((a, b) => b.matchScore - a.matchScore)
  .slice(0, 3);

// 5. Format output for n8n
return topCourses.map(course => ({ json: course }));

// 1. Grab candidate profile
const profile = $('Profile Agent').first().json.output || $('Profile Agent').first().json;

// 2. Gather top results from your 3 parallel nodes
const topJobs = $('Job match agent').all().map(item => item.json); 
const topSchemes = $('Scheme match agent').all().map(item => item.json);
const topCourses = $('Skill gap agent').all().map(item => item.json)
const jobMatchRaw = $('Job match agent').first().json;


// 3. Return a single merged payload
return [{
  json: {
    profile: profile,
    targetJob: topJobs[0] || {}, 
    allMatchedJobs: topJobs,
    matchedSchemes: topSchemes,
    recommendedCourses: topCourses
  }
}];

// Helper to safely convert plain text line breaks to HTML
function textToHtml(text) {
  if (!text) return 'N/A';
  return text
    // 1. Converts '### Heading' into clean <b>Heading</b> tags
    .replace(/^###\s*(.*$)/gim, '<b>$1</b><br>')
    .replace(/^##\s*(.*$)/gim, '<b>$1</b><br>')
    .replace(/^#\s*(.*$)/gim, '<b>$1</b><br>')

    // 2. Safely handles HTML characters and line breaks
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\n/g, "<br>");
}

// Extract data from incoming nodes
const combined = $('Combine agent data').first().json;
const rawResume = $('Resume Agent').first().json;
const resumeData = rawResume.output || rawResume;

const profile = combined.profile || {};
// Safely handles output whether coming from an AI Agent or a Code Node
const rawJobs = combined.allMatchedJobs || $('Job match agent').first().json;
const jobs = Array.isArray(rawJobs) ? rawJobs : (rawJobs.output || rawJobs.jobs || []);
const schemes = combined.matchedSchemes || [];
const courses = combined.recommendedCourses || [];

// Format sections cleanly using <b> tags

const jobsFormatted = jobs.map((job, index) => 
  `• <b>${index + 1}. ${job.title}</b> (${job.category || 'General'})<br>` +
  `   - <b>Required Skills:</b> ${job.requiredSkills ? job.requiredSkills.join(', ') : 'N/A'}<br>` +
  `   - <b>Location:</b> ${job.location || 'Any'}<br>` +
  `   - <b>Match Score:</b> ${job.matchScore || '80'}%`
).join('<br><br>');

const schemesFormatted = schemes.map((scheme, index) => 
  `• <b>${index + 1}. ${scheme.name}</b> (${scheme.category})<br>` +
  `   - <b>Description:</b> ${scheme.description}<br>` +
  `   - <b>Min Education:</b> ${scheme.minEducation}`
).join('<br><br>');

const roadmapFormatted = courses.map((course, index) => 
  `• <b>Step ${index + 1}: ${course.courseName}</b> [${course.platform}]<br>` +
  `   - <b>Target Skills:</b> ${course.targetSkills ? course.targetSkills.join(', ') : 'N/A'}<br>` +
  `   - <b>Overview:</b> ${course.description}`
).join('<br><br>');

// Generate Final Clean HTML Output
const dashboardMarkdown = `
<h2>Career & Upskilling Dashboard for ${profile.name || 'User'}</h2>
<hr>

<h3>Profile Snapshot</h3>
• <b>Education:</b> ${profile.education_level || 'N/A'}<br>
• <b>Skills:</b> ${profile.skills ? profile.skills.join(', ') : 'N/A'}<br>
• <b>Location:</b> ${profile.location || 'N/A'}<br>
• <b>Interest Area:</b> ${profile.interest_area || 'N/A'}<br>

<hr>

<h3>Top Recommended Job Matches</h3>
${jobsFormatted || 'No matching jobs found.'}

<hr>

<h3>Top Eligible Government Schemes</h3>
${schemesFormatted || 'No matching schemes found.'}

<hr>

<h3>Learning & Skill Gap Roadmap</h3>
${roadmapFormatted || 'No courses recommended.'}

<hr>

<h3>Tailored Resume & Cover Letter</h3>

<h4>Professional Summary</h4>
${textToHtml(resumeData.resume_summary)}

<hr>

<h4>Generated Full Resume</h4>
${textToHtml(resumeData.full_resume)}

<hr>

<h4>Generated Cover Letter</h4>
${textToHtml(resumeData.cover_letter)}
`;

return [{
  json: {
    dashboard_markdown: dashboardMarkdown,
    cover_letter: resumeData.cover_letter || 'N/A',
    full_resume: resumeData.full_resume || 'N/A',
    resume_summary: resumeData.resume_summary || 'N/A'
  }
}];

